// specs/module-page-accessibility.spec.ts
// Spec file — Module Page Accessibility Verification
// Source: .github/ui/input.txt (raw-file) — "Page Accessibility Verification"
// Generated by: ui-testcase-orchestrator
//
// Verifies that an authenticated Admin user can access each module reachable from the
// multi-tenant sidebar navigation. Each module is opened via the sidebar and asserted
// through its page object (URL + page heading) — no raw selectors in this spec.
//
// NOTE: The raw story also lists "Users", "Roles" and "IP Restrictions". These modules
// are NOT present in this application's navigation (multi-tenant or site-scoped) as of
// the analyzed environment, so they are intentionally omitted here (see conversion
// warnings in the run report) rather than asserted against fabricated locators.
import { test, expect } from '@playwright/test';
import { LoginPage } from '../pages/login.page';
import { MultiTenantDashboardPage } from '../pages/multi-tenant-dashboard.page';
import { TenantsPage } from '../pages/tenants.page';
import { ActivityReportPage } from '../pages/activity-report.page';
import { SitesPage } from '../pages/sites.page';
import { GeoFencePage } from '../pages/geo-fence.page';
import { ManageServiceEndpointsPage } from '../pages/manage-service-endpoints.page';
import { ManageDevicesPage } from '../pages/manage-devices.page';
import { config } from '../config/test-config';

test.describe('Module Page Accessibility Verification', () => {
  let loginPage: LoginPage;
  let dashboardPage: MultiTenantDashboardPage;
  let tenantsPage: TenantsPage;
  let activityReportPage: ActivityReportPage;
  let sitesPage: SitesPage;
  let geoFencePage: GeoFencePage;
  let manageServiceEndpointsPage: ManageServiceEndpointsPage;
  let manageDevicesPage: ManageDevicesPage;

  test.beforeEach(async ({ page }) => {
    loginPage = new LoginPage(page);
    dashboardPage = new MultiTenantDashboardPage(page);
    tenantsPage = new TenantsPage(page);
    activityReportPage = new ActivityReportPage(page);
    sitesPage = new SitesPage(page);
    geoFencePage = new GeoFencePage(page);
    manageServiceEndpointsPage = new ManageServiceEndpointsPage(page);
    manageDevicesPage = new ManageDevicesPage(page);

    // Authenticate and land on the multi-tenant dashboard with a tenant selected.
    await loginPage.goto();
    await loginPage.login(config.username, config.password);
    await dashboardPage.assertMultiTenantDialogVisible();
    await dashboardPage.clickChooseTenantDropdown();
    await dashboardPage.selectFirstTenantOption();
    await dashboardPage.assertIsDashboard();
  });

  // Source: input.txt | Scenario: Page Accessibility Verification (Admin)
  test('Admin user can access all modules available in the sidebar navigation', async ({ page }) => {

    await test.step('Verify the sidebar exposes the expected navigation modules', async () => {
      console.log('▶ Verify the sidebar exposes the expected navigation modules');
      const navItems = await dashboardPage.getNavMenuItems();
      expect(navItems).toEqual(
        expect.arrayContaining([
          'Dashboard',
          'Tenants',
          'Activity Report',
          'Sites',
          'Geo Fence',
          'Manage Service EndPoints',
          'Manage Devices',
        ]),
      );
    });

    await test.step('Access the Tenants module', async () => {
      console.log('▶ Access the Tenants module');
      await dashboardPage.clickNavItem('Tenants');
      await tenantsPage.assertAccessible();
      await page.screenshot({ path: 'test-results/screenshots/module-page-accessibility-tenants.png' });
    });

    await test.step('Access the Activity Report module', async () => {
      console.log('▶ Access the Activity Report module');
      await dashboardPage.clickNavItem('Activity Report');
      await activityReportPage.assertAccessible();
      await page.screenshot({ path: 'test-results/screenshots/module-page-accessibility-activity-report.png' });
    });

    await test.step('Access the Sites module', async () => {
      console.log('▶ Access the Sites module');
      await dashboardPage.clickNavItem('Sites');
      await sitesPage.assertAccessible();
      await page.screenshot({ path: 'test-results/screenshots/module-page-accessibility-sites.png' });
    });

    await test.step('Access the Geo Fence module', async () => {
      console.log('▶ Access the Geo Fence module');
      await dashboardPage.clickNavItem('Geo Fence');
      await geoFencePage.assertAccessible();
      await page.screenshot({ path: 'test-results/screenshots/module-page-accessibility-geo-fence.png' });
    });

    await test.step('Access the Manage Service EndPoints module', async () => {
      console.log('▶ Access the Manage Service EndPoints module');
      await dashboardPage.clickNavItem('Manage Service EndPoints');
      await manageServiceEndpointsPage.assertAccessible();
      await page.screenshot({ path: 'test-results/screenshots/module-page-accessibility-manage-service-endpoints.png' });
    });

    await test.step('Access the Manage Devices module', async () => {
      console.log('▶ Access the Manage Devices module');
      await dashboardPage.clickNavItem('Manage Devices');
      await manageDevicesPage.assertAccessible();
      await page.screenshot({ path: 'test-results/screenshots/module-page-accessibility-manage-devices.png' });
    });

    await test.step('Return to the Dashboard module', async () => {
      console.log('▶ Return to the Dashboard module');
      await dashboardPage.clickNavItem('Dashboard');
      await dashboardPage.assertIsDashboard();
      await page.screenshot({ path: 'test-results/screenshots/module-page-accessibility-dashboard.png' });
    });
  });
});
